  await sub(t,'真实写作身份取得安全包并写入授权 Candidate',async()=>{ordinaryBundle=await compile();ordinaryCandidate=await candidateFor('writerA',ordinaryBundle);const row=await using('admin',async c=>(await c.query(`SELECT actor_id,task_id,bundle_id,generation_id FROM ${q('candidate_version')} WHERE candidate_id=$1`,[ordinaryCandidate.candidate_id])).rows[0]);safe(row.actor_id==='writerA'&&row.task_id===task.writerA&&row.bundle_id===ordinaryBundle.bundle_id,'candidate_real_chain');return JSON.stringify({safeBundle:true,authorizedCandidate:true,realWorkflowTaskBundle:true});});
