  for(const [fn,args] of [['caller',[]],['current_policy',[]],['authorize',[task.writerA,'read_design']],['digest',['untrusted']],['grant_live',[grants.writerA.compile_context]],['projection',[null,null]],['audit',['writerA','read_context',null,null,null,'allow','forged',null]],['assert_bundle',['fake']]])await sub(t,`内部辅助函数 ${fn} 无执行权`,()=>sqlDenied('writerA',`SELECT ${q(fn)}(${args.map((_,i)=>`$${i+1}`).join(',')})`,args));
  for(const table of ['resource','design_revision','capability_grant','data_scope','access_audit_record','context_bundle','context_item','context_source_reference','candidate_version'])await sub(t,`写作身份不能直接写入 ${table}`,()=>sqlDenied('writerA',`INSERT INTO ${q(table)} DEFAULT VALUES`));
  for(const operation of ['read_design','validate','manage_grant','read_audit'])await sub(t,`写作身份不能调用 ${operation} 高权限入口`,async()=>{await expectedDeny(api('writerA',operation,operation==='validate'?{candidate_id:ordinaryCandidate.candidate_id}:operation==='manage_grant'?{grant_id:grants.writerA.read_context}:{task_id:task.writerA}));return {stage:'tool_boundary',evidence:'restricted_function_execute_denied; safe_external_error'};});
  for(const [field,value] of [['actor_id','author'],['scope_id',scopeIds.author],['project_id','project_b'],['scene_id','scene_b'],['viewpoint_id','hero_other'],['canon_watermark','999'],['policy_version','safe-context-v0'],['filtered_context',{text:canary}]])await sub(t,`伪造 ${field} 不能提权`,async()=>{await expectedDeny(api('writerA','compile_context',{task_id:task.writerA,[field]:value}));return 'request_extra_fields_denied';});
  for(const tid of [task.writerB,task.pov,task.future,task.peer])await sub(t,`真实未授权 Task ${tid} 拒绝`,async()=>{await expectedDeny(api('writerA','compile_context',{task_id:tid}));return 'server_task_scope_or_pov_watermark_denied';});
  await sub(t,'会话参数不能伪造数据库主体',async()=>using('writerA',async c=>{await c.query(`SELECT set_config('app.actor_id','author',false),set_config('app.scope_id',$1,false)`,[scopeIds.author]);const denied=await sqlApi(c,'api_compile_context',{task_id:task.writerB});safe(denied.ok===false,'guc_cannot_escalate');const allowed=await sqlApi(c,'api_get_context',{bundle_id:ordinaryBundle.bundle_id});safe(allowed.ok,'own_identity_retained');scan(allowed,'guc_context');return 'custom_guc_ignored; session_user_identity_retained';}));
