async function auditEventsFor(rr){return using('admin',async c=>(await c.query(`SELECT * FROM ${q('access_audit_record')} WHERE task_id=$1 AND restricted_resource_id=$2 ORDER BY audit_id`,[task.writerA,rr.resource_id])).rows);}
async function auditRefsFor(rr){return using('admin',async c=>(await c.query(`SELECT sr.*,i.bundle_id,st.task_id,st.project_id,st.scene_id,st.viewpoint_id,st.canon_watermark AS task_watermark FROM ${q('context_source_reference')} sr JOIN ${q('context_item')} i USING(item_id) JOIN ${q('context_bundle')} b USING(bundle_id) JOIN ${q('scene_task_version')} st USING(task_id) WHERE sr.resource_id=$1 ORDER BY sr.reference_id`,[rr.resource_id])).rows);}
function noAuditIdentifiers(response,rr,refs=[]){
  const serialized=JSON.stringify(response);
  for(const value of [rr.resource_id,rr.source_version_id,...refs.flatMap(ref=>[ref.reference_id,ref.item_id])])safe(!serialized.includes(value),'nested_forbidden_audit_identifier_absent');
}
async function rawAuditPreserved(before){const after=await using('admin',async c=>(await c.query(`SELECT * FROM ${q('access_audit_record')} WHERE audit_id=ANY($1::bigint[]) ORDER BY audit_id`,[before.map(e=>e.audit_id)])).rows);equal(after,before,'original_audit_rows_and_references_unchanged');}
